import copy
import json
import sys
from scenario_kernel.platform.consumer import _graph_providers
from scenario_kernel.platform.execution_graph import SemanticExecutionGraphScheduler
from scenario_kernel.adapters import SemanticTransformationEngine
from scenario_kernel.adapters.semantic_transformation_evaluator import evaluate, _Refusal

request = json.loads(sys.stdin.readline())
plan, root = request['plan'], request['input']
physical = set(request['physicalCellIds'])
pure = _graph_providers(plan, root, None, {}, None)
cells = {cell['cellId']: cell for cell in plan['canonicalGraph']['cells']}
collections = {}

def provider(value, context):
    if context.cell_id not in physical:
        expression = context.configuration
        if isinstance(expression, dict) and expression.get('kind') == 'invoke-port':
            return pure[context.provider_profile_id](value, context)
        if not isinstance(expression, dict) or 'op' not in expression:
            if cells[context.cell_id]['execution']['authorityId'] == 'mechanic:identity.v1':
                return {'outcomeValue': value, 'outcomeVariant': 'VALUE'}
            raise RuntimeError('UNDECLARED_EXECUTION_MECHANIC:' + context.cell_id)
        try:
            entering = context.decomposition_input if context.decomposition_input is not None else value
            scope = {'input': entering, 'root': root}
            outcome = evaluate(expression, scope)
            if outcome is None:
                raise ValueError('LEXICAL_BINDING_NOT_AVAILABLE_AT_CELL_ALTITUDE')
            if expression['op'] in {'map', 'flat-map', 'filter', 'find', 'some', 'every'}:
                occurrence = collections.get(context.cell_id, 0)
                collections[context.cell_id] = occurrence + 1
                source = evaluate(expression.get('from', {}), scope)
                return {'outcomeValue': outcome, 'outcomeVariant': 'CONTINUE' if occurrence < (len(source) if isinstance(source, list) else 0) else 'STOP'}
            return {'outcomeValue': outcome}
        except (KeyError, TypeError, ValueError, _Refusal):
            return {'outcomeValue': value, 'outcomeVariant': 'VALUE'}
    print(json.dumps({'type': 'invoke-provider', 'cellId': context.cell_id,
        'cellExecutionId': context.cell_execution_id, 'rootExecutionId': context.root_execution_id,
        'input': value}, ensure_ascii=False), flush=True)
    reply = json.loads(sys.stdin.readline())
    if 'error' in reply:
        raise RuntimeError(reply['error'])
    return {'outcomeValue': reply['outcome']}

authorities = {entry['id']: entry for entry in plan.get('bindingAuthorities', [])}
def project_binding(identity, value):
    authority = authorities[identity]
    return SemanticTransformationEngine().transform(authority['binding']['configuration']['expression'], value, root)

providers = {entry['providerProfileId']: provider for entry in plan['realizationOverlay']['providerBindings']}
result = SemanticExecutionGraphScheduler(plan, providers, project_binding).execute(copy.deepcopy(root), request['rootExecutionId'])
print(json.dumps({'type': 'result', 'result': result}, ensure_ascii=False), flush=True)
